// Debounced callbacks, as the price slider and the destination field use
// them. In benchmark mode the timer is replaced by an explicit flush that the
// benchmark step triggers, which is the workload's only change to the app's
// behaviour.
import { useCallback, useEffect, useRef } from "react";
import { benchmarkMode } from "./env.js";

const waiting = new Map();

export function flushDebounced() {
    const calls = [...waiting.values()];
    waiting.clear();
    for (const call of calls)
        call();
}

export function hasDebounced() {
    return waiting.size > 0;
}

export function debounce(callback, delay) {
    let timer = null;
    const key = {};
    const debounced = (...args) => {
        if (benchmarkMode) {
            waiting.set(key, () => callback(...args));
            return;
        }
        clearTimeout(timer);
        timer = setTimeout(() => callback(...args), delay);
    };
    debounced.cancel = () => {
        waiting.delete(key);
        clearTimeout(timer);
    };
    return debounced;
}

export function useDebouncedCallback(callback, delay) {
    const latest = useRef(callback);
    latest.current = callback;
    const debounced = useRef(null);
    if (!debounced.current)
        debounced.current = debounce((...args) => latest.current(...args), delay);
    useEffect(() => () => debounced.current.cancel(), []);
    return useCallback((...args) => debounced.current(...args), []);
}
