// A small span recorder in the spirit of OpenTelemetry's tracer: spans
// around GraphQL requests and React commits, exported in batches through the
// tracker.
import { tracker } from "./tracker.js";

let nextId = 1;
const finished = [];

function spanId() {
    return (nextId++).toString(16).padStart(16, "0");
}

class Span {
    constructor(name, attributes, parent) {
        this.name = name;
        this.attributes = { ...attributes };
        this.spanId = spanId();
        this.traceId = parent?.traceId ?? `${this.spanId}${this.spanId}`;
        this.parentId = parent?.spanId ?? null;
        this.start = typeof performance === "undefined" ? 0 : performance.now();
        this.events = [];
        this.ended = false;
    }

    setAttribute(key, value) {
        this.attributes[key] = value;
        return this;
    }

    addEvent(name, attributes) {
        this.events.push({ name, attributes, time: performance.now() });
        return this;
    }

    end() {
        if (this.ended)
            return;
        this.ended = true;
        this.duration = performance.now() - this.start;
        finished.push(this);
        if (finished.length >= 4)
            exportSpans();
    }
}

export function startSpan(name, attributes = {}, parent = null) {
    return new Span(name, attributes, parent);
}

export function exportSpans() {
    if (!finished.length)
        return;
    const spans = finished.splice(0).map((span) => ({
        name: span.name,
        traceId: span.traceId,
        spanId: span.spanId,
        parentSpanId: span.parentId,
        attributes: Object.entries(span.attributes).map(([key, value]) => ({ key, value: { stringValue: String(value) } })),
        events: span.events,
        durationMs: Math.round(span.duration * 1000) / 1000,
    }));
    tracker.push("spans", "otel.export", { resourceSpans: [{ resource: { "service.name": "travel-search-web" }, spans }] });
}
