// Apollo Client as the site configures it: automatic persisted queries over
// an HTTP link, a span per operation, and an InMemoryCache with type
// policies. The build doesn't define __DEV__, so Apollo runs its dev-mode
// checks, such as deep-freezing results, as it does on the reference site.
import { ApolloClient, ApolloLink, HttpLink, InMemoryCache, Observable, from } from "@apollo/client";
import { createPersistedQueryLink } from "@apollo/client/link/persisted-queries";
import { sha256 } from "js-sha256";
import { isServer } from "./env.js";
import { startSpan } from "./telemetry/spans.js";
import { workloadFetch } from "./transport.js";

export const possibleTypes = {
    CardBadge: ["DealBadge", "QualityBadge", "SustainabilityBadge", "ScarcityBadge"],
    FilterControl: ["CheckboxListControl", "RangeSliderControl", "StepperListControl"],
};

export const typePolicies = {
    Query: {
        fields: {
            accommodationSearch: { keyArgs: ["input"] },
            autocomplete: { keyArgs: ["input", ["query"]] },
        },
    },
    PropertySearchCard: { keyFields: ["id"] },
    PropertyBasics: { keyFields: ["id"], merge: true },
    FilterGroup: { keyFields: ["field"] },
    FilterOption: { keyFields: ["urlId"] },
    SortOption: { keyFields: ["id"] },
    AccommodationType: { keyFields: ["id"] },
    PropertyDetails: { keyFields: ["id"] },
    GuestReview: { keyFields: ["id"] },
    LocalizedString: { keyFields: false },
    LocalizedText: { keyFields: false },
    MonetaryAmount: { keyFields: false },
    WishlistStatus: { keyFields: false, merge: true },
};

const spanLink = new ApolloLink((operation, forward) => new Observable((observer) => {
    const span = startSpan(`graphql.${operation.operationName}`, { "graphql.operation.type": "query", "graphql.operation.name": operation.operationName });
    const subscription = forward(operation).subscribe({
        next(result) {
            span.addEvent("result", { errors: result.errors?.length ?? 0 });
            observer.next(result);
        },
        error(error) {
            span.setAttribute("error", true).end();
            observer.error(error);
        },
        complete() {
            span.end();
            observer.complete();
        },
    });
    return () => subscription.unsubscribe();
}));

export function createCache() {
    return new InMemoryCache({ possibleTypes, typePolicies });
}

export function createApolloClient({ cache = createCache(), link } = {}) {
    return new ApolloClient({
        cache,
        ssrMode: isServer,
        name: "travel-search-web",
        version: "2026.10.3",
        link: link ?? from([
            spanLink,
            createPersistedQueryLink({ sha256: (query) => sha256(query), useGETForHashedQueries: false }),
            new HttpLink({ uri: "/gql/graphql", fetch: workloadFetch, credentials: "same-origin" }),
        ]),
    });
}
